let syncPanelRequest=0;
let mqState={wf:"",view:"timeline",by:"deadline",q:"",client:"",nearOnly:false};
const isoWeek=iso=>{const d=new Date(iso+"T00:00:00Z"),day=(d.getUTCDay()+6)%7;d.setUTCDate(d.getUTCDate()-day+3);const first=new Date(Date.UTC(d.getUTCFullYear(),0,4));return 1+Math.round(((d-first)/864e5-3+((first.getUTCDay()+6)%7))/7);};
const shortD=iso=>new Date(iso+"T00:00:00Z").toLocaleString("en",{day:"numeric",month:"short",timeZone:"UTC"});
const NEAR_DAYS=1;
function weekLabel(due,today){
  const mon=mondayOf(due),sun=addIso(mon,6),cur=mondayOf(today),diff=Math.round((Date.parse(mon)-Date.parse(cur))/6048e5);
  return {key:mon,title:"Week "+isoWeek(due)+" · "+shortD(mon)+" to "+shortD(sun),tag:diff===0?"this week":diff===1?"next week":diff>1?"in "+diff+" weeks":""};
}
function queueCard(i,today){
  const ageDays=Math.max(0,Math.round((Date.parse(today)-Date.parse(i.ird))/864e5)),act=i.kind==="case"?'<button type="button" class="btn sm" data-opencase="'+esc(i.id)+'">Open</button>':'<button type="button" class="btn sm" data-review="'+esc(i.id)+'">Open</button>';
  return '<article class="acard mq'+(i.overdue?" r-red":i.daysLeft!==null&&i.daysLeft<=NEAR_DAYS?" r-amber":"")+'"><div class="ac-main"><div class="ac-meta" style="margin:0 0 6px">'+prioBadge(i.priority)+' <span class="agechip" title="Weeks since the IRD">In queue week '+(Math.floor(ageDays/7)+1)+'</span> '+(i.flags||[]).map(f=>'<span class="badge '+(f==="serious"||f==="returned"?"red":"blue")+'">'+({icsr:"Likely ICSR",serious:"Serious",returned:"Returned"})[f]+'</span>').join(" ")+'</div><div class="ac-title" style="-webkit-line-clamp:2">'+esc(i.title)+'</div><div class="ac-meta">'+esc(i.ref)+(i.clientName?' · '+esc(i.clientName):"")+(i.molecule?' · '+esc(i.molecule):"")+'</div>'+irdLine(i.ird,i.due,i.daysLeft,WF_NAME[i.workflow]+" due")+(i.override?'<div class="sub">Date set by a manager'+(i.override.reason?': '+esc(i.override.reason):"")+'</div>':"")+'</div><div class="ac-side"><div class="sub">'+dueText(i)+'</div>'+act+'</div></article>';
}
async function loadMyQueue(){
  const box=$("mqbox");if(!box)return;const allowed=wfAllowed();if(!allowed.includes(mqState.wf))mqState.wf=allowed[0];
  try{
    const r=await api("planner",{workflow:mqState.wf,person:data.viewer.role==="manager"?data.viewer.email:undefined,client:mqState.client});if(!$("mqbox"))return;
    const today=r.today;let items=r.items.filter(i=>i.workflow===mqState.wf);const total=items.length,q=mqState.q.trim().toLowerCase();
    if(q)items=items.filter(i=>(i.title+" "+i.ref+" "+i.molecule+" "+i.clientName).toLowerCase().includes(q));
    const near=items.filter(i=>i.overdue||(i.daysLeft!==null&&i.daysLeft<=NEAR_DAYS)).sort((a,b)=>String(a.due).localeCompare(String(b.due))||b.priority.score-a.priority.score),rest=items.filter(i=>!near.includes(i)).sort((a,b)=>String(a.due).localeCompare(String(b.due))||b.priority.score-a.priority.score);
    const counts=w=>r.items.filter(i=>i.workflow===w).length;
    const tabs='<div class="steptiles">'+allowed.map(w=>'<button type="button" class="steptile'+(w===mqState.wf?" on":"")+'" data-mqwf="'+w+'"><span class="st-n">'+({screening:"1",qc:"2",medical:"3"})[w]+'</span><span class="st-t"><b>'+WF_NAME[w]+'</b><span class="sub">'+({screening:"Screen and route to QC",qc:"Check and route on",medical:"Review, sign, release"})[w]+'</span></span><span class="st-c">'+counts(w)+'</span></button>').join("")+'</div>';
    const clientSel=(r.clients||[]).length?'<label class="fl"><span class="sub">Client</span><select id="mqclient"><option value="">All clients</option>'+r.clients.map(c=>'<option value="'+esc(c.id)+'"'+(mqState.client===c.id?" selected":"")+'>'+esc(c.name)+'</option>').join("")+'<option value="none"'+(mqState.client==="none"?" selected":"")+'>No client</option></select></label>':"";
    const ctl='<div class="filters slim" style="border:0;padding:0 0 10px"><input id="mqq" type="search" placeholder="Search title, reference, molecule" value="'+esc(mqState.q)+'" aria-label="Search the queue">'+clientSel+'</div>';
    const tl=r.timelines,days={screening:tl.screenDays,qc:tl.qcDays,medical:tl.medicalDays}[mqState.wf];
    const nearHtml=near.length?'<section class="mqnear"><div class="body"><h3 class="mqh">Needs you first <span class="badge red">'+near.length+'</span></h3><div class="sub" style="margin-bottom:10px">Overdue, or due today or tomorrow. Oldest deadline first.</div><div class="plist">'+near.map(i=>queueCard(i,today)).join("")+'</div></div></section>':"";
    const weeks={},order=[];rest.forEach(i=>{const w=weekLabel(i.due,today);if(!weeks[w.key]){weeks[w.key]={w,list:[]};order.push(w.key);}weeks[w.key].list.push(i);});
    const weekHtml=order.map(k=>{const g=weeks[k];return '<section><div class="body"><h3 class="mqh">'+esc(g.w.title)+(g.w.tag?' <span class="badge'+(g.w.tag==="this week"?" blue":"")+'">'+g.w.tag+'</span>':"")+' <span class="sub">'+g.list.length+' item'+(g.list.length===1?"":"s")+'</span></h3><div class="plist">'+g.list.map(i=>queueCard(i,today)).join("")+'</div></div></section>';}).join("");
    const empty=!items.length?'<div class="empty">'+(total?"Nothing matches your search.":"Nothing in your "+WF_NAME[mqState.wf]+" queue right now.")+'</div>':"";
    const byTog='<div class="fbar" style="margin:0 0 10px"><button type="button" class="fchip'+(mqState.by==="deadline"?" on":"")+'" data-mqby="deadline">By deadline</button><button type="button" class="fchip'+(mqState.by==="client"?" on":"")+'" data-mqby="client">By client</button></div>';
    const clientHtml=()=>{const cl={};items.forEach(i=>{const c=(cl[i.clientName||"No client"]||={items:[],mol:{}});c.items.push(i);(c.mol[i.molecule||i.portfolio]||=[]).push(i);});
      const order=Object.entries(cl).sort((a,b)=>b[1].items.filter(i=>i.overdue).length-a[1].items.filter(i=>i.overdue).length||b[1].items.length-a[1].items.length);
      return order.map(([name,c])=>{const late=c.items.filter(i=>i.overdue).length,soon=c.items.filter(i=>!i.overdue&&i.daysLeft!==null&&i.daysLeft<=NEAR_DAYS).length,ser=c.items.filter(i=>(i.flags||[]).includes("serious")).length,nd=c.items.map(i=>i.due).filter(Boolean).sort()[0]||"";
        return '<section class="clientcard"><div class="body"><h3 class="mqh">'+esc(name)+' <span class="badge">'+c.items.length+' open</span>'+(late?' <span class="badge red">'+late+' overdue</span>':"")+(soon?' <span class="badge amber">'+soon+' due soon</span>':"")+(ser?' <span class="badge red">'+ser+' serious</span>':"")+(nd?' <span class="sub">next due '+esc(nd)+'</span>':"")+'</h3>'+
          Object.entries(c.mol).sort((a,b)=>b[1].filter(i=>i.overdue).length-a[1].filter(i=>i.overdue).length||b[1].length-a[1].length).map(([m,list])=>'<div class="cc-mol"><div class="cc-mh"><b>'+esc(m)+'</b><span class="sub">'+list.length+' item'+(list.length===1?"":"s")+(list.filter(i=>i.overdue).length?' · '+list.filter(i=>i.overdue).length+' overdue':"")+'</span></div><div class="plist">'+list.slice().sort((a,b)=>String(a.due).localeCompare(String(b.due))||b.priority.score-a.priority.score).map(i=>queueCard(i,today)).join("")+'</div></div>').join("")+'</div></section>';}).join("");};
    const addBtn="";
    box.innerHTML=tabs+ctl+'<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">'+byTog+addBtn+'</div><p class="sub" style="margin:0 0 12px">'+WF_NAME[mqState.wf]+': '+days+' working day'+(days===1?"":"s")+' from the IRD'+(mqState.wf==="screening"?" to screen and route to QC":"")+(mqState.by==='client'?'. Grouped by client and molecule; the most overdue client is first.':'. Items nearing their deadline come first, then everything else by week.')+'</p>'+(mqState.by==='client'?clientHtml():nearHtml+weekHtml)+empty;
    if($("mqq"))$("mqq").oninput=e=>{mqState.q=e.target.value;const pos=e.target.selectionStart;clearTimeout(mqState.t);mqState.t=setTimeout(()=>{loadMyQueue().then(()=>{const el=$("mqq");if(el){el.focus();el.setSelectionRange(pos,pos);}});},200);};
  }catch(e){box.innerHTML='<div class="sub">'+esc(e.message)+'</div>';}
}
const WS_GROUPS=[["Literature",[["pubmed","PubMed (NCBI)","US National Library of Medicine"],["pmc","PubMed Central (NCBI)","NCBI full-text archive: finds drugs named only in the body of a paper"],["europepmc","Europe PMC","Europe, with preprints and patents"],["openalex","OpenAlex","Journals and repositories in every region"],["crossref","Crossref","Publisher records, worldwide"],["doaj","DOAJ","Open-access journals"],["core","CORE","Open repositories (needs a key in Settings)"]]],["Trials",[["clinicaltrials","ClinicalTrials.gov","Registered trials, worldwide"]]],["Regulators",[["mhra","UK MHRA","Drug Safety Update and alerts"],["fdarecall","US FDA recalls","Drug enforcement reports"]]]];
