const SCAN_NAME={product:"Product",event:"Event",dose:"Dose",timing:"Timing",dechallenge:"Dechallenge",rechallenge:"Rechallenge",outcome:"Outcome",causality:"Causality",lab:"Lab value",patient:"Patient"};
let scanCtx=null;
function scanSentence(u,only){
  let out="",pos=0;
  for(const sp of u.spans){if(only&&sp.kind!==only)continue;out+=esc(u.text.slice(pos,sp.start))+'<mark class="sc sc-'+sp.kind+'" title="'+esc(SCAN_NAME[sp.kind])+'">'+esc(u.text.slice(sp.start,sp.end))+'</mark>';pos=sp.end;}
  return out+esc(u.text.slice(pos));
}
function drawScan(){
  const c=scanCtx,r=c.scan,only=c.only,box=$("scanbody");
  const chips=Object.entries(r.counts).map(([k,n])=>'<button type="button" class="sc-chip sc-'+k+(only===k?" on":"")+'" data-scanfilter="'+k+'">'+esc(SCAN_NAME[k])+' <b>'+n+'</b></button>').join("");
  const sections={};r.units.filter(u=>!only||u.spans.some(sp=>sp.kind===only)).forEach(u=>{(sections[u.section||"Text"]||=[]).push(u);});
  const ev=r.events.length?table(["Event in the article","MedDRA suggestion (confirm in MedDRA)","IME list"],r.events.map(e=>[esc(e.term),e.meddra.length?e.meddra.map(m=>esc(m.llt.name)+" → "+esc(m.pt.name)+' <span class="sub">LLT '+esc(m.llt.code)+' · '+esc(m.match)+'</span>').join("<br>"):(r.meddraLoaded?'<span class="sub">no exact match</span>':'<span class="sub">load MedDRA in Settings</span>'),e.ime.length?esc(e.ime[0].pt)+(e.ime[0].code?' <span class="sub">'+esc(e.ime[0].code)+'</span>':""):'<span class="sub">—</span>']),""):'<div class="sub">No events detected.</div>';
  const ai=c.ai.available?'<div style="margin:10px 0"><button type="button" class="btn outline sm" data-scanai="1">Ask AI to check the events</button> <span class="sub">Uses tokens. Sends only the tagged sentences with personal data masked. Never runs on its own.</span></div>':'<div class="sub" style="margin:10px 0">AI check is off, so no tokens are used.'+(data.viewer.role==="manager"?" Turn it on in Settings.":"")+'</div>';
  const aiRes=c.aiRes?('<div class="card" style="padding:12px;margin-bottom:12px"><b>AI-proposed events</b> <span class="sub">'+c.aiRes.tokens+' tokens used · '+c.aiRes.used+' of '+c.aiRes.limit+' this month</span>'+(c.aiRes.events.length?c.aiRes.events.map((e,i)=>'<div class="row" style="align-items:flex-start"><span><b>'+esc(e.term)+'</b> '+(e.serious?badge("serious","red"):"")+'<div class="sub">“'+esc(e.quote)+'”</div></span>'+(curCase&&$("casedlg").open&&curCase.canEdit!==false?'<button type="button" class="btn outline sm" data-scanadd="'+i+'">Add to case</button>':"")+'</div>').join(""):'<div class="sub">Nothing it proposed could be confirmed from the text.</div>')+(c.aiRes.dropped.length?'<div class="sub" style="margin-top:6px">Dropped, because the quote is not in the article: '+esc(c.aiRes.dropped.join(", "))+'</div>':"")+'</div>'):"";
  box.innerHTML='<div class="sub">'+esc(r.title)+'</div><div class="sub">Source: '+esc(r.source)+' · '+r.sentences+' sentences scanned · '+r.patients+' patient'+(r.patients===1?"":"s")+' found · '+r.authors.length+' author'+(r.authors.length===1?"":"s")+'</div>'+
    '<div class="chips" style="margin:10px 0">'+chips+(only?'<button type="button" class="sc-chip" data-scanfilter="">Show all</button>':"")+'</div>'+ai+aiRes+
    '<h3 style="margin:10px 0 6px">Events and codes</h3>'+ev+
    '<h3 style="margin:14px 0 6px">Authors (all are reporters)</h3>'+(r.authors.length?r.authors.map(a=>'<span class="badge'+(a.corresponding?" blue":"")+'" title="'+esc(a.affiliation)+'">'+esc(a.name)+(a.corresponding?" · corresponding":"")+(a.email?" · "+esc(a.email):"")+'</span>').join(" "):'<span class="sub">No author data.</span>')+
    '<h3 style="margin:14px 0 6px">Full text</h3>'+Object.entries(sections).map(([sec,us])=>'<div class="sub" style="margin-top:8px"><b>'+esc(sec)+'</b></div>'+us.map(u=>'<p class="scp">'+scanSentence(u,only)+'</p>').join("")).join("");
}
